1	/** Flat fee added to every premium, regardless of the items insured. */
2	const PROCESSING_FEE = 5;
3	
4	/** Base premium of each insurable item type. */
5	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	  rune: 25,
11	  moonstone: 25,
12	};
13	
14	/** Initial assessment surcharge on a customer's first insurance. */
15	const FIRST_INSURANCE_RATE = 0.1;
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type QuoteStep = { op: string; items: Item[] };
25	
26	export type Damage = { itemType: string; amount: number };
27	
28	export type Incident = { cause: string; damages: Damage[] };
29	
30	export type ClaimStep = { op: string; policy: number; incident: Incident };
31	
32	export type Step = QuoteStep | ClaimStep;
33	
34	export type Item = { type: string } & Record<string, unknown>;
35	
36	export type QuoteResult = { premium: number };
37	
38	export type ClaimResult = { payout: number; remainingCap: number };
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export type ScenarioOutcome = { results: Result[] };
43	
44	/** A block is exactly this many items of one and the same type. */
45	const BLOCK_SIZE = 3;
46	
47	/** Special base premium charged for a complete block, instead of the per-item sum. */
48	const BLOCK_BASE_PREMIUM = 60;
49	
50	/** Number of items of each type on a policy. */
51	const countByType = (items: Item[]): Map<string, number> => {
52	  const counts = new Map<string, number>();
53	  for (const item of items) {
54	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
55	  }
56	  return counts;
57	};
58	
59	/** Base premium of a single item of the given type, before block pricing or surcharge. */
60	const basePremiumOfType = (type: string): number => BASE_PREMIUM_BY_TYPE[type];
61	
62	/** Base premium for all items of one and the same type. */
63	const groupBasePremium = (type: string, count: number): number =>
64	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
65	
66	/** Base premium of a policy covering the given items. */
67	const calculateBasePremium = (items: Item[]): number =>
68	  [...countByType(items)].reduce(
69	    (total, [type, count]) => total + groupBasePremium(type, count),
70	    0,
71	  );
72	
73	/** Risk surcharge charged on the base premium of a cursed item. */
74	const CURSE_RATE = 0.5;
75	
76	/** Enchantment level from which an item counts as highly enchanted. */
77	const HIGH_ENCHANTMENT_LEVEL = 5;
78	
79	/** Risk surcharge charged on the base premium of a highly enchanted item. */
80	const HIGH_ENCHANTMENT_RATE = 0.3;
81	
82	/** True when the item is enchanted strongly enough to attract the surcharge. */
83	const isHighlyEnchanted = (item: Item): boolean =>
84	  typeof item.enchantment === "number" &&
85	  item.enchantment >= HIGH_ENCHANTMENT_LEVEL;
86	
87	/** Combined rate of the surcharges an item attracts. */
88	const itemSurchargeRate = (item: Item): number => {
89	  const curseRate = item.cursed ? CURSE_RATE : 0;
90	  const enchantmentRate = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_RATE : 0;
91	  return curseRate + enchantmentRate;
92	};
93	
94	/** Surcharges an individual item attracts, charged on its own base premium. */
95	const itemSurcharges = (item: Item): number =>
96	  basePremiumOfType(item.type) * itemSurchargeRate(item);
97	
98	/** Surcharges that attach to individual items rather than to the whole policy. */
99	const calculateItemSurcharges = (items: Item[]): number =>
100	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
101	
102	/** Years of business from which a customer counts as long-standing. */
103	const LOYALTY_YEARS = 2;
104	
105	/** Discount a long-standing customer receives on the policy base premium. */
106	const LOYALTY_RATE = -0.2;
107	
108	/** True when the customer has been with MHPCO long enough to earn the discount. */
109	const isLongStanding = (customer: Customer): boolean =>
110	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
111	
112	/** Discount on every contract after the customer's first. */
113	const FOLLOW_UP_RATE = -0.15;
114	
115	/** True when this is not the customer's first contract. */
116	const isFollowUpContract = (
117	  _customer: Customer,
118	  previousContracts: number,
119	): boolean => previousContracts > 0;
120	
121	/**
122	 * Rates that attach to the policy as a whole. Each applies to the policy base
123	 * premium; positive rates are surcharges, negative ones discounts.
124	 */
125	const POLICY_RATES: {
126	  rate: number;
127	  applies: (customer: Customer, previousContracts: number) => boolean;
128	}[] = [
129	  { rate: FIRST_INSURANCE_RATE, applies: () => true },
130	  { rate: LOYALTY_RATE, applies: isLongStanding },
131	  { rate: FOLLOW_UP_RATE, applies: isFollowUpContract },
132	];
133	
134	/** Net of every policy-wide rate the customer qualifies for. */
135	const policyRate = (customer: Customer, previousContracts: number): number =>
136	  POLICY_RATES.reduce(
137	    (total, { rate, applies }) =>
138	      applies(customer, previousContracts) ? total + rate : total,
139	    0,
140	  );
141	
142	/** Net policy-wide adjustment, charged on the policy base premium. */
143	const calculatePolicyAdjustment = (
144	  policyBasePremium: number,
145	  customer: Customer,
146	  previousContracts: number,
147	): number => policyBasePremium * policyRate(customer, previousContracts);
148	
149	/** Premiums are rounded up — fractions of a gold piece fall to MHPCO. */
150	const roundPremiumUp = (amount: number): number => Math.ceil(amount);
151	
152	/** Price a policy covering the given items. */
153	const quotePremium = (
154	  items: Item[],
155	  customer: Customer,
156	  previousContracts: number,
157	): number => {
158	  const policyBasePremium = calculateBasePremium(items);
159	  const surcharges = calculateItemSurcharges(items);
160	  const policyAdjustment = calculatePolicyAdjustment(
161	    policyBasePremium,
162	    customer,
163	    previousContracts,
164	  );
165	  return roundPremiumUp(
166	    policyBasePremium + surcharges + policyAdjustment + PROCESSING_FEE,
167	  );
168	};
169	
170	/** Sum insured for each item type, per the MHPCO price list. */
171	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
172	  sword: 1000,
173	  amulet: 600,
174	  staff: 800,
175	  potion: 400,
176	  rune: 250,
177	  moonstone: 250,
178	};
179	
180	/** Excess the claimant bears on every damaged item. */
181	const DEDUCTIBLE = 100;
182	
183	/** A policy pays out at most this multiple of its insurance sum. */
184	const CAP_MULTIPLIER = 2;
185	
186	/** Total sum insured under a policy covering the given items. */
187	const insuranceSum = (items: Item[]): number =>
188	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
189	
190	/** Enchantment level from which damage is only partly reimbursed. */
191	const REDUCED_REIMBURSEMENT_LEVEL = 8;
192	
193	/** Share of the damage MHPCO reimburses on a heavily enchanted item. */
194	const REDUCED_REIMBURSEMENT_RATE = 0.5;
195	
196	/** Share of the damage MHPCO reimburses for the given insured item. */
197	const reimbursementRate = (item: Item): number =>
198	  typeof item.enchantment === "number" &&
199	  item.enchantment >= REDUCED_REIMBURSEMENT_LEVEL
200	    ? REDUCED_REIMBURSEMENT_RATE
201	    : 1;
202	
203	/** What MHPCO owes for a single damaged item, before the cap is considered. */
204	const damagePayout = (damage: Damage, item: Item): number =>
205	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
206	
207	/** A quoted policy, tracked so later claim steps can draw against its cap. */
208	type Policy = { items: Item[]; remainingCap: number };
209	
210	/** The policy a quote step establishes, with its cap untouched. */
211	const openPolicy = (items: Item[]): Policy => ({
212	  items,
213	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
214	});
215	
216	/** The insured item a damage entry refers to. */
217	const damagedItem = (policy: Policy, damage: Damage): Item =>
218	  policy.items.find((item) => item.type === damage.itemType)!;
219	
220	/** What MHPCO owes for an entire incident, before the cap is considered. */
221	const grossIncidentPayout = (incident: Incident, policy: Policy): number =>
222	  incident.damages.reduce(
223	    (total, damage) => total + damagePayout(damage, damagedItem(policy, damage)),
224	    0,
225	  );
226	
227	/** Payouts are rounded down — fractions of a gold piece stay with MHPCO. */
228	const roundPayoutDown = (amount: number): number => Math.floor(amount);
229	
230	/**
231	 * Draws an amount owed against the policy's cap. A policy never pays out more
232	 * than the cap it has left, so the amount drawn is whichever is smaller.
233	 */
234	const drawAgainstCap = (policy: Policy, amountOwed: number): number => {
235	  const drawn = Math.min(roundPayoutDown(amountOwed), policy.remainingCap);
236	  policy.remainingCap -= drawn;
237	  return drawn;
238	};
239	
240	/** True when the step reports damage against a policy rather than asking for a price. */
241	const isClaimStep = (step: Step): step is ClaimStep => step.op === "claim";
242	
243	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
244	  const policies = new Map<number, Policy>();
245	  let previousContracts = 0;
246	
247	  const handleQuote = (step: QuoteStep, stepIndex: number): QuoteResult => {
248	    const premium = quotePremium(
249	      step.items,
250	      scenario.customer,
251	      previousContracts,
252	    );
253	    previousContracts += 1;
254	    policies.set(stepIndex, openPolicy(step.items));
255	    return { premium };
256	  };
257	
258	  const handleClaim = (step: ClaimStep): ClaimResult => {
259	    const policy = policies.get(step.policy)!;
260	    const payout = drawAgainstCap(
261	      policy,
262	      grossIncidentPayout(step.incident, policy),
263	    );
264	    return { payout, remainingCap: policy.remainingCap };
265	  };
266	
267	  const results = scenario.steps.map((step, stepIndex): Result =>
268	    isClaimStep(step) ? handleClaim(step) : handleQuote(step, stepIndex),
269	  );
270	
271	  return { results };
272	};
